def calculate_sum_set_size(k):
    N = 87  # t_0 to t_86

    def get_t(i, k):
        if i <= k:
            return 2 * i
        else:
            return 2 * i - 1

    sum_set = set()
    for i in range(N):
        for j in range(i, N):
            t_i = get_t(i, k)
            t_j = get_t(j, k)
            sum_set.add(t_i + t_j)

    return len(sum_set)

# Test edge cases
size_k0 = calculate_sum_set_size(0)
size_k85 = calculate_sum_set_size(85)

# Search for the minimum size over all possible k (0 <= k <= 85)
min_size = float('inf')
optimal_k = -1

for k in range(86):
    size = calculate_sum_set_size(k)
    if size < min_size:
        min_size = size
        optimal_k = k

